 * URI reference parsing, RFC 3986 §5.2 resolution, and normalization.
 *
 * A parsed URI reference is `{ scheme, authority, path, query, fragment }`
 * where an absent component is `undefined` and a present-but-empty one is
 * `''`. `path` is always a string (it is required by the generic syntax,
 * even when empty).
 */

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21',
}

/** Error carrying the name of the component whose percent-encoding is truncated. */
export class TruncatedPercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/** Parses a URI reference into its five generic components. */
export function parseReference(input) {
  let scheme
  let rest = input
  let schemeEnd = -1
  for (let i = 0; i < input.length; i++) {
    const c = input[i]
    if (c === ':') {
      schemeEnd = i
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }
  if (schemeEnd !== -1) {
    scheme = input.slice(0, schemeEnd)
    rest = input.slice(schemeEnd + 1)
  }

  let authority
  let pathQueryFragment = rest
  if (rest.startsWith('//')) {
    let authEnd = rest.length
    for (let i = 2; i < rest.length; i++) {
      const c = rest[i]
      if (c === '/' || c === '?' || c === '#') {
        authEnd = i
        break
      }
    }
    authority = rest.slice(2, authEnd)
    pathQueryFragment = rest.slice(authEnd)
  }

  const fragStart = pathQueryFragment.indexOf('#')
  const fragment = fragStart === -1 ? undefined : pathQueryFragment.slice(fragStart + 1)
  const beforeFragment = fragStart === -1 ? pathQueryFragment : pathQueryFragment.slice(0, fragStart)

  const queryStart = beforeFragment.indexOf('?')
  const path = queryStart === -1 ? beforeFragment : beforeFragment.slice(0, queryStart)
  const query = queryStart === -1 ? undefined : beforeFragment.slice(queryStart + 1)

  return { scheme, authority, path, query, fragment }
}

/** Splits an authority into userinfo, host and port, each following the rules stated in the spec. */
function splitAuthority(authority) {
  if (authority === undefined) return { userinfo: undefined, host: undefined, port: undefined }

  let userinfo
  let rest = authority
  const lastAt = authority.lastIndexOf('@')
  if (lastAt !== -1) {
    userinfo = authority.slice(0, lastAt)
    rest = authority.slice(lastAt + 1)
  }

  const lastBracket = rest.lastIndexOf(']')
  const searchStart = lastBracket === -1 ? 0 : lastBracket
  const colon = rest.indexOf(':', searchStart)
  let host
  let port
  if (colon !== -1) {
    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  } else {
    host = rest
  }

  return { userinfo, host, port }
}

function joinAuthority({ userinfo, host, port }) {
  let out = ''
  if (userinfo !== undefined) out += userinfo + '@'
  out += host
  if (port !== undefined) out += ':' + port
  return out
}

function isHexDigit(c) {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

function isUnreserved(c) {
  return (
    (c >= 'A' && c <= 'Z') ||
    (c >= 'a' && c <= 'z') ||
    (c >= '0' && c <= '9') ||
    c === '-' ||
    c === '.' ||
    c === '_' ||
    c === '~'
  )
}

/**
 * Uppercases the hex digits of every `%XX` triplet and replaces it with the
 * character it encodes when that character is unreserved. Throws a bare
 * `Error` (no component attached) when a `%` lacks two following hex digits;
 * callers attach the component name.
 */
function normalizePercentEncodings(value) {
  let out = ''
  for (let i = 0; i < value.length; i++) {
    const c = value[i]
    if (c !== '%') {
      out += c
      continue
    }
    const a = value[i + 1]
    const b = value[i + 2]
    if (a === undefined || b === undefined || !isHexDigit(a) || !isHexDigit(b)) {
      throw new Error('truncated percent-encoding')
    }
    const hex = (a + b).toUpperCase()
    const code = parseInt(hex, 16)
    const decoded = String.fromCharCode(code)
    out += isUnreserved(decoded) ? decoded : '%' + hex
    i += 2
  }
  return out
}

function asciiLower(value) {
  let out = ''
  for (const c of value) out += c >= 'A' && c <= 'Z' ? c.toLowerCase() : c
  return out
}

/** Removes dot segments from a path per RFC 3986 §5.2.4. */
function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = output.slice(0, output.lastIndexOf('/') === -1 ? 0 : output.lastIndexOf('/'))
    } else if (input === '/..') {
      input = '/'
      output = output.slice(0, output.lastIndexOf('/') === -1 ? 0 : output.lastIndexOf('/'))
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const match = input.match(/^\/?[^/]*/)
      const segment = match[0]
      output += segment
      input = input.slice(segment.length)
    }
  }
  return output
}

/**
 * Normalizes a parsed reference into its final form and returns the
 * reconstructed string. Throws `TruncatedPercentEncodingError` when a
 * percent-encoding is malformed, checking path, userinfo, host, query and
 * fragment in that order.
 */
export function normalize(parsed) {
  const scheme = parsed.scheme !== undefined ? asciiLower(parsed.scheme) : undefined
  const { userinfo, host, port } = splitAuthority(parsed.authority)

  const checks = [
    ['path', parsed.path],
    ['userinfo', userinfo],
    ['host', host],
    ['query', parsed.query],
    ['fragment', parsed.fragment],
  ]
  const normalized = {}
  for (const [name, value] of checks) {
    if (value === undefined) continue
    try {
      normalized[name] = normalizePercentEncodings(value)
    } catch {
      throw new TruncatedPercentEncodingError(name)
    }
  }

  let normalizedHost = normalized.host
  if (normalizedHost !== undefined) normalizedHost = asciiLower(normalizedHost)

  let normalizedPort = port
  const defaultPort = scheme !== undefined ? DEFAULT_PORTS[scheme] : undefined
  if (normalizedPort === '' || (defaultPort !== undefined && normalizedPort === defaultPort)) {
    normalizedPort = undefined
  }

  let path = removeDotSegments(normalized.path)
  const authorityPresent = parsed.authority !== undefined
  if (authorityPresent && path === '') path = '/'

  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (authorityPresent) {
    out += '//' + joinAuthority({ userinfo: normalized.userinfo, host: normalizedHost, port: normalizedPort })
  }
  out += path
  if (normalized.query !== undefined) out += '?' + normalized.query
  if (normalized.fragment !== undefined) out += '#' + normalized.fragment
  return out
}

function mergePaths(base, refPath) {
  if (base.authority !== undefined && base.path === '') return '/' + refPath
  const lastSlash = base.path.lastIndexOf('/')
  if (lastSlash === -1) return refPath
  return base.path.slice(0, lastSlash + 1) + refPath
}

/**
 * Resolves a reference against a base per RFC 3986 §5.2.2 (strict mode) and
 * returns the resolved, unnormalized components.
 */
export function resolveReference(base, ref) {
  const target = {}
  if (ref.scheme !== undefined) {
    target.scheme = ref.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else if (ref.authority !== undefined) {
    target.scheme = base.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else if (ref.path === '') {
    target.scheme = base.scheme
    target.authority = base.authority
    target.path = base.path
    target.query = ref.query !== undefined ? ref.query : base.query
  } else {
    target.scheme = base.scheme
    target.authority = base.authority
    target.path = ref.path.startsWith('/') ? removeDotSegments(ref.path) : removeDotSegments(mergePaths(base, ref.path))
    target.query = ref.query
  }
  target.fragment = ref.fragment
  return target
}
"}

